public static int findNthLeapYear(int Y, int N) {
    int year = Y + 1;
    int count = 0;
    while (count < N) {
        if (isLeapYear(year)) {
            count++;
            if (count == N) {
                return year;
            }
        }
        year++;
    }
    return -1; // Should never reach here if N is positive
}

private static boolean isLeapYear(int year) {
    return (year % 4 == 0 && year % 100 != 0) || (year % 400 == 0);
}
