public static int calculateTimeNeeded(int N) {
    if (N <= 1) return 0;
    if (N % 2 == 0) return N * (N - 1) / (N - 2);
    else return N * (N - 1) / (N - 2) - 1;
}

public static int calculateTimeNeeded(int N) {
int time = 0;
if (N % 2 == 0) {
    int[] people = new int[N];
    for (int i = 0; i < N; i++) {
        people[i] = i;
    }
    int target = 0;
    while (target % 2 == 0) {
        for (int i = 0; i < N - 1; i++) {
            if (people[i] == target || people[i + 1] == target) {
                if (people[i] == target && people[i + 1] == (target + 1) % N) {
                    // They are already consecutive, no need to swap
                    continue;
                } else if (people[i] == target) {
                    // Swap with right
                    int temp = people[i];
                    people[i] = people[i + 1];
                    people[i + 1] = temp;
                    time++;
                    target = (target + 2) % N;
                } else {
                    // Swap with left
                    int temp = people[i];
                    people[i] = people[i + 1];
                    people[i + 1] = temp;
                    time++;
                    target = (target + 2) % N;
                }
            }
        }
    }
} else {
    int[] people = new int[N];
    for (int i = 0; i < N; i++) {
        people[i] = i;
    }
    int[] target = new int[] {0, 2, 4};
    for (int t = 1; t < 3; t++) {
        int pos = -1;
        for (int i = 0; i < N; i++) {
            if (people[i] == target[t]) {
                pos = i;
                break;
            }
        }
        // Move target[t] to position t
        int steps = pos - t;
        time += steps;
        // Shift elements
        for (int i = pos; i > t; i--) {
            people[i] = people[i - 1];
        }
        people[t] = target[t];
    }
}
return time;
}

