private static void floodFill(char[][] grid, int i, int j, int rows, int cols) {
    if (i < 0 || i >= rows || j < 0 || j >= cols || grid[i][j] != '@') {
        return;
    }

    grid[i][j] = '*';

    floodFill(grid, i, j + 1, rows, cols);
    floodFill(grid, i + 1, j, rows, cols);
    floodFill(grid, i, j - 1, rows, cols);
    floodFill(grid, i - 1, j, rows, cols);
