        boolean found = false;
        // Check if numbers[i] is even and there exists a j != i such that numbers[j] == target
        if (numbers[i] % 2 == 0) {
            for (int j = 0; j < numbers.length; j++) {
                if (i != j && numbers[j] == target) {
                    found = true;
                    break;
                }
            }
        }
        if (found) {
            count++;
        }
    }
