public static String appx(String word1, String word2) {
    int count = 0;
    char[] chars1 = word1.toCharArray();
    char[] chars2 = word2.toCharArray();
    for (char c : chars1) {
        for (char d : chars2) {
            if (c == d) {
                count++;
                break;
            }
        }
    }
    int totalLength = word1.length() + word2.length();
    if (totalLength == 0) {
        return "appx(" + word1 + ", " + word2 + ") = 0";
    }
    int gcd = gcd(count, totalLength);
    int numerator = count / gcd;
    int denominator = totalLength / gcd;
    if (denominator == 1) {
        return "appx(" + word1 + ", " + word2 + ") = " + numerator;
    } else {
        return "appx(" + word1 + ", " + word2 + ") = " + numerator + "/" + denominator;
    }
}

private static int gcd(int a, int b) {
    a = Math.abs(a);
    b = Math.abs(b);
    if (b == 0) {
        return a;
    }
    return gcd(b, a % b);
}
