public static String appx(String word1, String word2) {
    // Count common letters case-insensitively
    String upper1 = word1.toUpperCase();
    String upper2 = word2.toUpperCase();

    // Count frequency of each character in word1
    Map<Character, Integer> freq1 = new HashMap<>();
    for (char c : upper1.toCharArray()) {
        freq1.put(c, freq1.getOrDefault(c, 0) + 1);
    }

    // Count common letters by iterating through word2
    int common = 0;
    for (char c : upper2.toCharArray()) {
        if (freq1.containsKey(c) && freq1.get(c) > 0) {
            common++;
            freq1.put(c, freq1.get(c) - 1);
        }
    }

    int sumLengths = word1.length() + word2.length();

    // Reduce the fraction common/sumLengths
    int num = common;
    int den = sumLengths;

    if (num == 0) {
        return String.format("appx(%s, %s) = 0", word1, word2);
    }

    int gcd = gcd(num, den);
    int reducedNum = num / gcd;
    int reducedDen = den / gcd;

    String fraction;
    if (reducedDen == 1) {
        fraction = String.valueOf(reducedNum);
    } else {
        fraction = reducedNum + "/" + reducedDen;
    }

    return String.format("appx(%s, %s) = %s", word1, word2, fraction);
}

private static int gcd(int a, int b) {
    while (b != 0) {
        int temp = b;
        b = a % b;
        a = temp;
    }
    return a;
}
