private int dfs(int node, int parent, List<List<Integer>> adj, boolean[] hasApple, int[] dp) {
    if (dp[node] != -1) {
        return dp[node];
    }

    int total = 0;
    for (int neighbor : adj.get(node)) {
        if (neighbor == parent) continue;
        int childCost = dfs(neighbor, node, adj, hasApple, dp);
