public String sortString(String s) {
    if (s == null || s.length() == 0) {
        return s;
    }

    int[] freq = new int[26];
    for (char c : s.toCharArray()) {
        freq[c - 'a']++;
    }

    StringBuilder result = new StringBuilder();
    int n = s.length();

    while (result.length() < n) {
        // Ascending pass
        for (int i = 0; i < 26; i++) {
            if (freq[i] > 0) {
                result.append((char) ('a' + i));
                freq[i]--;
            }
        }

        // Descending pass
        for (int i = 25; i >= 0; i--) {
            if (freq[i] > 0) {
                result.append((char) ('a' + i));
                freq[i]--;
            }
        }
    }

    return result.toString();
}
