public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n < 2) {
        return false;
    }
    int sum = 0;
    int minVal = Integer.MAX_VALUE;
    int maxVal = Integer.MIN_VALUE;
    for (int num : nums) {
        sum += num;
        if (num < minVal) minVal = num;
        if (num > maxVal) maxVal = num;
    }

    // The sum of one subarray with size k must be sum * k / n
    // So sum * k must be divisible by n
    for (int k = 1; k < n; k++) {
        if (sum * k % n != 0) {
            continue;
        }
        int target = sum * k / n;
        if (target < minVal * k || target > maxVal * k) {
            continue;
        }
        if (check(nums, n, k, target)) {
            return true;
        }
    }
    return false;
}

private boolean check(int[] nums, int n, int k, int target) {
    // Use memoization/memoized DFS or bit-level DP
    // Since n can be up to 20, we can use a Set of states (index, count, sum)
    // Or use a boolean array for sum values
    // Better: use a Set of encoded states for memoization

    // Let's use a Set of long-encoded states: (pos, count, sum)
    // But sum can be large, so let's use a different approach.

    // Actually, for n<=20, k<=10, target is bounded.
    // Let's use memoization with a HashSet of String or encoded longs.

    // Alternative: use a 3D boolean DP but sum range might be large.
    // Let's use memoization with a Set.

    return dfs(nums, n, k, 0, 0, target, new HashSet<>());
}

private boolean dfs(int[] nums, int n, int k, int pos, int count, int target, Set<String> memo) {
    if (count == k) {
        return target == 0;
    }
    if (pos == n) {
        return false;
    }
    if (n - pos < k - count) {
        return false;
    }
    // If the remaining sum can't reach the target
    int remaining = target;
    if (!memo.contains(pos + "," + count + "," + remaining)) {
        // Try including nums[pos]
        if (dfs(nums, n, k, pos + 1, count + 1, remaining - nums[pos], memo)) {
            return true;
        }
        // Try excluding nums[pos]
        if (dfs(nums, n, k, pos + 1, count, remaining, memo)) {
            return true;
        }
        memo.add(pos + "," + count + "," + remaining);
    }
    return false;
}
