    // For n up to 16, we can use meet-in-the-middle. But let me try DP first 
    // with a reasonable bound.

    // Actually, let's use a different approach: iterate over all possible subset 
    // sizes k from 1 to n/2, and use a set of integers to track the possible 
    // sums for that size.

    // Initialize: for k=0, sum=0 is possible.
    // But we need non-empty subsets, so k from 1 to n/2.

    // Let's use a list of hash sets, where index k contains all possible sums 
    // for subsets of size k.

    List<Set<Integer>> sums = new ArrayList<>();
    for (int i = 0; i <= n / 2; i++) {
        sums.add(new HashSet<>());
    }
    sums.get(0).add(0);

    for (int num : nums) {
        // Iterate from higher k to lower to avoid using the same element multiple times
        for (int k = n / 2; k >= 1; k--) {
            if (sums.get(k - 1).isEmpty()) {
                continue;
            }
            Set<Integer> prevSums = sums.get(k - 1);
            Set<Integer> currSums = sums.get(k);
            Set<Integer> newSums = new HashSet<>();
            for (int s : prevSums) {
                newSums.add(s + num);
            }
            currSums.addAll(newSums);
        }
    }

    for (int k = 1; k <= n / 2; k++) {
        if (sums.get(k).contains(k * avg)) {
            return true;
        }
    }

    return false;
