public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    int sum = 0;
    for (int num : nums) sum += num;

    // Check if it's possible to split into two parts with same average
    // For the average to be the same, sum/k must equal sum/(n-k)
    // i.e., sum * n = sum * k => but more generally, if we pick k elements,
    // their sum must be sum * k / n, which must be an integer.

    for (int k = 1; k <= n / 2; k++) {
        long target = (long) sum * k;
        if (target % n == 0) {
            if (canSplit(nums, k, (int) (target / n))) {
                return true;
            }
        }
    }
    return false;
}

private boolean canSplit(int[] nums, int k, int target) {
    // Use bitset / boolean array DP: dp[j][s] = true if we can pick j elements with sum s
    // To save memory, we can use a 2D boolean array or optimize.
    int n = nums.length;
    // Max sum of k elements
    int maxSum = target;
    boolean[][] dp = new boolean[k + 1][maxSum + 1];
    dp[0][0] = true;

    for (int num : nums) {
        for (int j = k; j >= 1; j--) {
            for (int s = maxSum; s >= num; s--) {
                dp[j][s] |= dp[j - 1][s - num];
            }
        }
    }
    return dp[k][target];
}
