    int n = nums.length;
    if (n < 2) return false;
    long sum = 0;
    for (int num : nums) sum += num;

    // The sum of the subset must be sum * k / n for some k (1 <= k <= n-1)
    // Equivalent to sum * k % n == 0
    // k is the size of the subset. We need to find k such that:
    // 1 <= k <= n-1 and sum * k % n == 0
    // Let's find all valid k values.

    // Note: We can assume WLOG that the subset size k <= n/2, because if there's a subset of size k > n/2 with average sum/n,
    // then its complement of size n-k < n/2 also has the same average.
    // So we only need to check k from 1 to n/2.

    int maxK = n / 2;
    int gcdVal = gcd(sum, n);
    // The valid k values are multiples of n/gcdVal that are <= maxK
    int step = n / gcdVal;

    // If no valid k, return false
