    // Actually, we can use a different approach: memoize by (remaining elements, count needed, remaining sum needed)

    // Let's sort the array to help with pruning
    java.util.Arrays.sort(nums);

    // Use a Set to cache results for (i, k, sumNeeded) where i is the next index to consider,
    // k is the number of elements still to pick, and sumNeeded is the remaining sum to achieve.
    java.util.Set<String> cache = new java.util.HashSet<>();

    for (int k = step; k <= maxK; k += step) {
