}

private boolean canPick(int[] nums, int n, int k, long target, java.util.Set<String> cache) {
    if (k == 0) {
        return target == 0;
    }
    if (k > n) return false;
    if (target <= 0) return false;

    // Lower bound: minimum possible sum of k smallest elements from the remaining
    // Upper bound: maximum possible sum of k largest elements from the remaining
    // Since nums is sorted, the remaining elements are nums[0..n-1] but we've been choosing from the start.
    // Actually, let's restructure: we process from index 0 to n-1.
    // The state should include the current index. Let me revise.

    // Better approach: use index-based DP.
    // Let's use a different helper.
    return helper(nums, 0, n, k, target, cache);
}

private boolean helper(int[] nums, int index, int n, int k, long target, java.util.Set<String> cache) {
    if (k == 0) {
        return target == 0;
    }
    if (index >= n) return false;
    if (k > n - index) return false;
    if (target <= 0) return false;

    String key = index + "," + k + "," + target;
    if (cache.contains(key)) return false;

    // Pruning: minimum possible sum from picking k from index..n-1
    // Since sorted, the k smallest are nums[index], nums[index+1], ..., nums[index+k-1]
    long minSum = 0;
    for (int i = index; i < index + k && i < n; i++) {
        minSum += nums[i];
        if (minSum > target) break;
    }
    if (minSum > target) {
        cache.add(key);
        return false;
    }

    // Pruning: maximum possible sum from picking k from index..n-1
    // The k largest are nums[n-k], ..., nums[n-1]
    long maxSum = 0;
    for (int i = n - k; i < n; i++) {
        maxSum += nums[i];
    }
    if (maxSum < target) {
        cache.add(key);
        return false;
    }

    // Choose nums[index]
    if (helper(nums, index + 1, n, k - 1, target - nums[index], cache)) {
        return true;
    }

    // Skip nums[index]
    if (helper(nums, index + 1, n, k, target, cache)) {
        return true;
    }

    cache.add(key);
    return false;
}

private static int gcd(long a, int b) {
    a = Math.abs(a);
    b = Math.abs(b);
    while (b != 0) {
        long temp = b;
        b = (int)(a % b);
        a = temp;
    }
    return (int)a;
}
