    int sum = 0;
    for (int num : nums) sum += num;

    // If sum * i is not divisible by n, no subset of size i can have the same average
    // Because average is sum/n, and for a subset of size i, sum_subset = i * sum / n
    // So i * sum must be divisible by n

    // We only need to check subset sizes up to n/2 (since if a subset of size k works,
    // the complement of size n-k also works)
    // Also, the subset size cannot be 0 or n

    // To reduce computation, check if there's a multiplier such that n divides i * (sum)
    // Actually, we can check all i from 1 to n/2

    for (int i = 1; i <= n / 2; i++) {
        if (sum * i % n != 0) continue;
        int target = (int)(sum * i / (long)n); // to avoid overflow, use long

        // Check if we can pick i elements from nums such that sum is target
        if (canPick(nums, i, target)) return true;
    }
    return false;
}

private boolean canPick(int[] nums, int k, int targetSum) {
    int n = nums.length;
    // We use DP: dp[i][j] = set of sums achievable by picking i elements from first j elements
    // This might be memory expensive, but let's try a more efficient approach

    // Alternatively, use a recursive helper with memoization
    boolean[][][] memo = new boolean[n + 1][k + 1][0]; // can't use this, targetSum varies

    // Let's use a different approach: recursive with memoization
    // State: index, count, current_sum
    // But current_sum can be large, so use a HashSet-based memo or an array-based DP

    // Let's use DP with a set for each (count, index)
    // dp[count] = set of sums achievable using exactly 'count' elements from first 'idx' elements

    // Start with a set containing {0} for count=0
    Set<Integer>[] dp = new Set[k + 1];
    for (int i = 0; i <= k; i++) {
        dp[i] = new HashSet<>();
    }
    dp[0].add(0);

    for (int idx = 0; idx < n; idx++) {
        // Process in reverse to avoid using same element multiple times in one step
        // Actually, we process one element at a time, so we need to update from right to left
        // for count, to avoid using the current element more than once
        for (int count = Math.min(idx + 1, k); count >= 1; count--) {
            Set<Integer> prevSet = dp[count - 1];
            Set<Integer> curSet = dp[count];
            Set<Integer> toAdd = new HashSet<>();
            for (int s : prevSet) {
                toAdd.add(s + nums[idx]);
            }
            curSet.addAll(toAdd);
        }
    }
    return dp[k].contains(targetSum);
}
