    for (int i = 2; i <= n; i++) {
        int upTwo = (i >= 2) ? cost[i - 2] + cost[i - 1] : cost[0] + cost[1];
        int upOne = (i >= 1) ? cost[i - 1] + (i >= 2 ? cost[i - 2] : 0) : cost[0];
        // Actually, let's use standard DP approach
        // Let dp[i] represent the minimum cost to reach step i
        // We need to compute cost up to index n (top), which is just after the last step
        // dp[i] = cost[i] + min(dp[i-1], dp[i-2])
        // Start: dp[0] = cost[0], dp[1] = cost[1]
        // We need to find min(dp[n-1], dp[n-2]) to get to the top (which is at index n)
        // Actually, we can modify iteratorically without storing all values
    }
    // Standard iterative DP with two variables
    int prevPrev = cost[0];
    int prev = cost[1];
    for (int i = 2; i < n; i++) {
        int current = cost[i] + Math.min(prevPrev, prev);
        prevPrev = prev;
        prev = current;
    }
    return Math.min(prevPrev, prev);
