public boolean hasAllCodes(String s, int k) {
    if (k > s.length()) {
        return false;
    }
    // Total number of binary strings of length k is 2^k
    int total = 1 << k;
    boolean[] seen = new boolean[total];
    int mask = (1 << k) - 1;
    int value = 0;

    for (int i = 0; i < s.length(); i++) {
        // Shift left by 1 and add the new bit
        value = ((value << 1) & mask) | (s.charAt(i) - '0');

        if (i >= k - 1) {
            seen[value] = true;
        }

        // Early exit if all codes have been found
        int count = 0;
        for (boolean b : seen) {
            if (b) count++;
        }
        if (count == total) {
            return true;
        }
    }

    return false;
