public int minOperations(int n) {
    // The array is arr[i] = 2*i + 1, so the array is [1, 3, 5, ..., 2*n-1]
    // The sum is n^2, so the target value is the average: n^2 / n = n
    // We need to compute the minimum number of operations to make all elements equal to n.
    // Since each operation moves 1 unit from one element to another, the total operations
    // is the total excess above the target, which equals the total deficit below the target.
    // We can compute this as the sum of |arr[i] - n| for all i divided by 2.

    // arr[i] = 2*i + 1, target = n
    // Excess: for indices where 2*i + 1 > n, the excess is (2*i + 1 - n)
    // Deficit: for indices where 2*i + 1 < n, the deficit is (n - (2*i + 1))
    // Since total excess = total deficit, the number of operations is the sum of excess (or sum of deficit).

    // Let's find the split point. 
    // arr[i] > n => 2*i + 1 > n => i > (n-1)/2
    // arr[i] < n => 2*i + 1 < n => i < (n-1)/2
    // If n is odd, (n-1)/2 is an integer, and that element equals n (since 2*((n-1)/2) + 1 = n).
    // If n is even, (n-1)/2 is not an integer.

    // Let's compute the sum of excess for i where 2*i + 1 > n.
    // The values of i where 2*i+1 > n start from floor((n+1)/2) to n-1.
    // Actually, let's just iterate and sum up the absolute differences, then divide by 2.
    // But we can also derive a formula.

    let k = n / 2;
    // The target is n.
    // The elements are: 1, 3, 5, ..., 2*n-1.
    // The elements below n are: 1, 3, ..., up to the largest 2*i+1 < n.
    // The number of elements below n is k = (n-1)/2 if n is odd, or n/2 if n is even? Let's check.
    // If n=3: elements < 3: 1 (since 3 is not less than 3). Count = 1. (n-1)/2 = 1.
    // If n=6: elements < 6: 1,3,5. Count=3. n/2 = 3.
    // If n=4: elements < 4: 1,3. Count=2. n/2=2.
    // If n=5: elements < 5: 1,3. Count=2. (n-1)/2=2.
    // So the count of elements strictly less than n is: 
    //   if n is odd: (n-1)/2
    //   if n is even: n/2
    // Which is just (n-1)/2 for all n? No: 
    //   n=6: (n-1)/2 = 2 (integer division), but actual count is 3.
    // So it's ceil((n-1)/2) = (n)/2 for even, (n-1)/2 for odd. That is: (n-1+1)/2 = n/2 using integer division? 
    // For n=6: n/2=3. For n=5: (5-1)/2=2, and 5/2=2 (integer division). So yes, it's n/2 using integer division for the count of elements less than n.

    // The sum of deficit (elements less than n):
    // The elements are: 1, 3, ..., 2*(k-1)+1 where k = n/2 (integer division).
    // The deficit for element 2*i+1 is n - (2*i+1).
    // Sum for i=0 to k-1: sum (n - 2*i - 1) = sum (n-1-2*i) from i=0 to k-1.
    // = k*(n-1) - 2 * (0+1+...+(k-1)) = k*(n-1) - 2 * (k*(k-1)/2) = k*(n-1) - k*(k-1) = k*(n-1-k+1) = k*(n-k).

    let k = n / 2;
    return k * (n - k);
}

