public int kthFactor(int n, int k) {
    int count = 0;
    for (int i = 1; i * i <= n; i++) {
        if (n % i == 0) {
            count++;
            if (count == k) {
                return i;
            }
        }
    }
    // Now check from sqrt(n) downwards for the larger factors
    int sqrt = (int) Math.sqrt(n);
    for (int i = sqrt; i >= 1; i--) {
        int factor = n / i;
        if (factor == i) {
            // avoid double counting the perfect square root
            break;
        }
        if (n % i == 0) {
            count++;
            if (count == k) {
                return factor;
            }
        }
    }
    return -1;
}
