private int dfs(String s, int start, Set<String> set, int maxLen) {
    if (start == maxLen) {
        return set.size();
    }
    int maxSub = 0;
    for (int end = start + 1; end <= maxLen; end++) {
        String sub = s.substring(start, end);
        if (set.contains(sub)) {
            continue;
        }
        set.add(sub);
        maxSub = Math.max(maxSub, dfs(s, end, set, maxLen));
        set.remove(sub);
    }
    return maxSub;
}
