public String getSmallestString(int n, int k) {
    char[] res = new char[n];
    // Initially all characters are 'a', which contributes n to the value
    k -= n;
    // Start from the rightmost position and make it as large as possible to keep left characters as small as possible
    for (int i = n - 1; i >= 0; i--) {
        // The maximum value a single character can add beyond 'a' is 25 (for 'z')
        if (k >= 25) {
            res[i] = 'z';
            k -= 25;
        } else {
            res[i] = (char) ('a' + k);
            k = 0;
        }
    }
    return new String(res);
}
