public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> result = new ArrayList<>();
    if (low > high) {
        return result;
    }
    // BFS/DFS approach using queue
    for (int i = 0; i <= 9; i++) {
        if (i >= low && i <= high) {
            result.add(i);
        }
        // Start BFS from each single-digit number
        Deque<Integer> queue = new LinkedList<>();
        if (i >= low && i <= high) {
            result.add(i);
        }
        queue.offer(i);
    }
    // Actually, let's do a cleaner BFS
    result.clear();
    for (int i = 1; i <= 9; i++) {
        if (i >= low && i <= high) {
            result.add(i);
        }
        Deque<Integer> queue = new LinkedList<>();
        queue.offer(i);
        while (!queue.isEmpty() && result.get(result.size() - 1) <= high) {
            int num = queue.pollFirst();
            // Generate next stepping numbers
            long lastDigit = num % 10;
            for (int diff = -1; diff <= 1; diff += 2) {
                int nextDigit = (int) lastDigit + diff;
                if (nextDigit >= 0 && nextDigit <= 9) {
                    long nextNum = (long) num * 10 + nextDigit;
                    if (nextNum <= high) {
                        if (nextNum >= low) {
                            result.add((int) nextNum);
                        }
                        queue.offer((int) nextNum);
                    }
                }
            }
        }
    }
    // Handle 0 specifically
    if (low <= 0 && 0 <= high) {
        result.add(0);
    }
    result.sort(Comparator.naturalOrder());
    return result;
}
