public static int longestLine(int[][] mat) {
    if (mat == null || mat.length == 0) return 0;

    int m = mat.length;
    int n = mat[0].length;
    int maxLen = 0;

    // dp[i][j] = current length of horizontal line ending at (i,j)
    // dv[i][j] = current length of vertical line ending at (i,j)
    // dd[i][j] = current length of diagonal line ending at (i,j)
    // da[i][j] = current length of anti-diagonal line ending at (i,j)

    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (mat[i][j] != 1) {
                continue;
            }

            int horiz = 1;
            if (j > 0 && mat[i][j - 1] == 1) {
                horiz = mat[i][j - 1] + 1;
            }
            mat[i][j] = horiz; // overwrite with horizontal length temporarily? No, we need separate tracking.

            // Let's use separate variables and update mat in place for horizontal.
            // Actually, better to use a 2D array or track separately. Let's use separate logic.
        }
    }

    // The above approach is messy. Let's do it properly with separate 2D arrays or in-place with careful handling.
    // We'll use in-place: only store the result for one direction (horizontal) and use separate vars for others on the fly.
    // Better: use a single pass with 4 directions stored in 4 2D arrays.

    int[][] horiz = new int[m][n];
    int[][] vert = new int[m][n];
    int[][] diag = new int[m][n];
    int[][] anti = new int[m][n];

    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                horiz[i][j] = (j > 0 ? horiz[i][j - 1] : 0) + 1;
                vert[i][j] = (i > 0 ? vert[i - 1][j] : 0) + 1;
                diag[i][j] = (i > 0 && j > 0 ? diag[i - 1][j - 1] : 0) + 1;
                anti[i][j] = (i > 0 && j < n - 1 ? anti[i - 1][j + 1] : 0) + 1;

                maxLen = Math.max(maxLen, Math.max(horiz[i][j], Math.max(vert[i][j], Math.max(diag[i][j], anti[i][j]))));
            }
        }
    }

    return maxLen;
