                    dp[i][j][0] = dp[i][j - 1][0] + 1;
                }
                // Vertical: up
                if (i == 0) {
                    dp[i][j][1] = 1;
                } else {
                    dp[i][j][1] = dp[i - 1][j][1] + 1;
                }
                // Diagonal: top-left
                if (i == 0 || j == 0) {
                    dp[i][j][2] = 1;
                } else {
                    dp[i][j][2] = dp[i - 1][j - 1][2] + 1;
                }
                // Anti-diagonal: top-right
                if (i == 0 || j == n - 1) {
                    dp[i][j][3] = 1;
                } else {
                    dp[i][j][3] = dp[i - 1][j + 1][3] + 1;
                }

                for (int k = 0; k < 4; k++) {
                    if (dp[i][j][k] > res) {
                        res = dp[i][j][k];
                    }
                }
            }
        }
    }

    return res;
}
