public static int squarePermutations(int[] A) {
    int n = A.length;
    if (n == 0) return 0;
    if (n == 1) return 1;

    // Cache for isSquare check
    int maxSum = 0;
    for (int a : A) {
        maxSum = Math.max(maxSum, a);
    }
    int[] squareStatus = new int[maxSum * 2 + 1];
    for (int i = 0; i <= maxSum * 2; i++) {
        squareStatus[i] = -1; // -1 means not computed
    }

    // Use bitmask DP to count permutations
    // dp[mask][last] = number of ways to arrange elements in mask ending with element at index 'last'
    int totalMasks = (1 << n);
    int[][] dp = new int[totalMasks][n];

    // Base case: single element
    for (int i = 0; i < n; i++) {
        dp[1 << i][i] = 1;
    }

    int count = 0;
    for (int mask = 3; mask < totalMasks; mask++) {
        for (int last = 0; last < n; last++) {
            if ((mask & (1 << last)) == 0) continue;
            if (dp[mask][last] == 0) continue;

            for (int next = 0; next < n; next++) {
                if ((mask & (1 << next)) != 0) continue;

                if (isSquare(A[last] + A[next], squareStatus)) {
                    int newMask = mask | (1 << next);
                    dp[newMask][next] += dp[mask][last];
                }
            }
        }
    }

    // Sum up all valid permutations (all masks with n bits set, for all last positions)
    int fullMask = totalMasks - 1;
    for (int last = 0; last < n; last++) {
        count += dp[fullMask][last];
    }

    return count;
}

private static boolean isSquare(int x, int[] squareStatus) {
    if (x < 0) return false;
    if (squareStatus[x] != -1) {
        return squareStatus[x] == 1;
    }
    int sqrt = (int) Math.sqrt(x);
    boolean isSq = (sqrt * sqrt == x);
    squareStatus[x] = isSq ? 1 : 0;
    return isSq;
}
