    // But we must be careful: the problem says two permutations are different if there exists an index with different value
    // So we need to count distinct value sequences. We can sort and use standard duplicate skipping in permutations

    // Approach: sort the array, then backtracking with duplicate skipping
    int[] sorted = A.clone();
    java.util.Arrays.sort(sorted);
    n = sorted.length;
    used = new int[n]; // all 0
    path = new int[n];

