private static int backtrackPerm(int[] sorted, int pos, int[] used, int[] path, int n) {
    if (pos == n) {
        return 1;
    }

    int count = 0;
    for (int i = 0; i < n; i++) {
        if (used[i] == 0) {
            // Check if we can place sorted[i] at position pos
            boolean valid = true;
            if (pos > 0) {
                int prevVal = path[pos - 1];
                if (!isPerfectSquare(prevVal + sorted[i])) {
                    valid = false;
                }
            }

            if (valid) {
                // Skip duplicates: if same element was tried in the same position (at same depth), skip
                // Standard duplicate skipping in permutations: if i > 0 and sorted[i] == sorted[i-1] and used[i-1] == 0, skip
                // But this only works if we are trying things in order and the previous identical was not chosen
                // Actually, the standard approach is: if i > 0 and sorted[i] == sorted[i-1] and used[i-1] is 0, 
                // then we are at the same level and haven't used the previous identical, so skip this one
                // because it would generate the same permutation
                if (i > 0 && sorted[i] == sorted[i - 1] && used[i - 1] == 0) {
                    continue;
                }

                used[i] = 1;
                path[pos] = sorted[i];
                count += backtrackPerm(sorted, pos + 1, used, path, n);
                used[i] = 0;
            }
        }
    }

    return count;
}
