public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return new int[0];
    }
    int rows = mat.length;
    int cols = mat[0].length;
    int total = rows * cols;
    int[] result = new int[total];
    int index = 0;
    // Traverse each diagonal sum from 0 to (rows-1 + cols-1)
    for (int sum = 0; sum <= rows + cols - 2; sum++) {
        if (sum % 2 == 0) {
            // Even sum: traverse from bottom to top (increasing col, decreasing row)
            int startCol = Math.min(sum, cols - 1);
            int startRow = sum - startCol;
            while (start.Row >= 0 && startCol <= cols - 1) {
                result[index++] = mat[startRow][startCol];
                startRow--;
                startCol++;
            }
        } else {
            // Odd sum: traverse from top to bottom (decreasing col, increasing row)
            int startRow = Math.min(sum, rows - 1);
            int startCol = sum - startRow;
            while (startRow <= rows - 1 && startCol >= 0) {
                result[index++] = mat[startRow][startCol];
                startRow++;
                startCol--;
            }
        }
    }
    return result;
}
