private static void helper(List<String> result, StringBuilder sb, int n, int len, int pos, Map<Character, Character> pairMap) {
    if (pos == n) {
        if (len == n) {
            result.add(sb.toString());
        }
        return;
    }

    for (int i = 0; i <= 9; i++) {
        char left = (char) ('0' + i);
        char right = pairMap.get(left);
        if (right == null) continue;

        if (left == '0' && len + 1 == 1 && n > 1 && pos == 0) {
            // skip leading zero for n > 1
            continue;
        }

        sb.append(left);
        if (pos == n - pos - 1 && n % 2 == 1) {
            // middle
            helper(result, sb, n, len + 1, pos + 1, pairMap);
        } else {
            sb.append(right);
            helper(result, sb, n, len + (pos == n - pos - 1 ? 1 : 2), pos + 1, pairMap);
        }
        sb.setLength(sb.length() - (pos == n - pos - 1 && n % 2 == 1 ? 1 : 2));
    }
