private static void helper(List<String> result, char[] pairs, char[][] pairMap, int n, int pos, int half, char[] buf) {
    if (pos == half) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++) {
            sb.append(buf[i]);
        }
        String num = sb.toString();
        if (n % 2 == 0 && !num.startsWith("0")) {
            result.add(num);
        } else if (n % 2 == 1) {
            if (!num.startsWith("0") || num.length() == 1) {
                result.add(num);
            }
        } else {
            if (!num.startsWith("0")) {
                result.add(num);
            }
        }
        return;
    }

    for (char c : pairs) {
        buf[pos] = c;
        buf[n - 1 - pos] = pairMap[getIndex(c, pairMap)][1];
        if (pos == 0) {
            helper(result, pairs, pairMap, n, pos + 1, half, buf);
        } else {
            helper(result, pairs, pairMap, n, pos + 1, half, buf);
        }
    }
}

