private static void generate(int n, int currLen, StringBuilder sb, List<String> result) {
    if (currLen == n) {
        result.add(sb.toString());
        return;
    }
    // Pairs: (0, 0), (1, 1), (6, 9), (8, 8), (9, 6)
    int[] left = {0, 1, 1, 8, 6, 9};
    int[] right = {0, 1, 6, 8, 9, 9};
    for (int i = 0; i < 6; i++) {
        // Avoid leading zero: if this is the first position, left must not be 0
        if (currLen == 0 && n > 1 && left[i] == 0) {
            continue;
        }
        sb.append(left[i]);
        // If we're adding the middle character (odd length and this is the middle), only right == left cases
        if (n - currLen == 1 && (left[i] == 0 || left[i] == 1 || left[i] == 8)) {
            sb.append(right[i]);
            generate(n, currLen + 2, sb, result);
            sb.deleteCharAt(sb.length() - 1);
        } else {
            sb.append(right[i]);
            generate(n, currLen + 2, sb, result);
            sb.deleteCharAt(sb.length() - 1);
        }
        sb.deleteCharAt(sb.length() - 1);
    }
}
