        StringBuilder sb = new StringBuilder();
        for (char c : left) {
            sb.append(c);
        }
        if (n % 2 == 1) {
            char middle = left[pos - 1];
            if (middle == '0' || middle == '1' || middle == '8') {
                sb.append(middle);
            } else {
                return;
            }
        }
        for (int i = right.length - 1; i >= 0; i--) {
            sb.append(right[i]);
        }
        if (n == 1 || left[0] != '0') {
            result.add(sb.toString());
        }
        return;
    }

    for (char c : map.keySet()) {
        if (pos == 0 && c == '0' && n > 1) {
            continue;
        }
        left[pos] = c;
        right[pos] = map.get(c);
        helper(n, pos + 1, left, right, map, result);
