public static boolean isBoomerang(int[][] points) {
    // Check if there are exactly 3 points
    if (points == null || points.length != 3) {
        return false;
    }

    int x1 = points[0][0], y1 = points[0][1];
    int x2 = points[1][0], y2 = points[1][1];
    int x3 = points[2][0], y3 = points[2][1];

    // Calculate squared distances to avoid floating point issues
    // If any two points are identical, it's not a boomerang
    long d12 = (x2 - x1) * 1L * (x2 - x1) + (y2 - y1) * 1L * (y2 - y1);
    long d23 = (x3 - x2) * 1L * (x3 - x2) + (y3 - y2) * 1L * (y3 - y2);
    long d13 = (x3 - x1) * 1L * (x3 - x1) + (y3 - y1) * 1L * (y3 - y1);

    // If any distance is zero, two points are the same
    if (d12 == 0 || d23 == 0 || d13 == 0) {
        return false;
    }

    // Check if the three points are collinear using the cross product
    // (x2 - x1) * (y3 - y1) - (x3 - x1) * (y2 - y1) == 0 means collinear
    long cross = (x2 - x1) * 1L * (y3 - y1) - (x3 - x1) * 1L * (y2 - y1);

    // If cross product is zero, points are collinear, not a boomerang
    return cross != 0;
}
