    int maxEnergy = 1;
    int count = 1;
    for (int i = 1; i < s.length(); i++) {
        if (s.charAt(i) == s.charAt(i - 1)) {
            count++;
            if (count > maxEnergy) {
                maxEnergy = count;
            }
        } else {
            count = 1;
        }
    }
    return maxEnergy;
}
