public static int calculateUniqueSum(int[] nums) {
    Set<Integer> seen = new HashSet<>();
    Set<Integer> added = new HashSet<>();
    int sum = 0;
    for (int num : nums) {
        if (!seen.contains(num) && !added.contains(num)) {
            seen.add(num);
        }
    }
    for (int num : nums) {
        if (seen.contains(num) && !added.contains(num)) {
            sum += num;
            added.add(num);
        }
    }
    return sum;
}
